// Фикстура интеграционного теста навмеша ($.nav.mesh).
//
// Та же арена 640×480 и та же стена-перегородка в колонке 10, что и в
// tests/fixtures/nav, но навигация строится прямоугольной декомпозицией:
// свободное пространство режется на прямоугольники, соседние связываются
// порталами, путь идёт по графу и сглаживается воронкой.
//
// В стене оставлены проходы сверху (ряды 0..2) и снизу (ряды 12..14), чтобы
// маршрут в обход был заведомо длиннее прямой. Герой стартует слева, «цель» —
// безтелесный узел справа.

$.ready(() => {
    $.world.gravity(0, 0).color('#0b1020');

    $.nav.clear();
    const mesh = $.nav.mesh({ x: 0, y: 0, w: 640, h: 480, cell: 32 });

    // Стена собрана из отдельных <wall>: так проверяется buildFromWalls,
    // который читает габариты узлов, а не только теги.
    for (let cy = 3; cy < 12; cy++) {
        $('<wall>', { class: 'blocker' })
            .at(10 * 32 + 16, cy * 32 + 16)
            .size(32, 32)
            .appendTo($.world);
    }
    // agentRadius — запас на габарит агента: герой 28×40, берём 20. Без него
    // декомпозиция подходит вплотную к стене и тело в неё упирается.
    mesh.buildFromWalls({ tags: ['wall'], inset: 0, agentRadius: 20 });
    $.nav.useMesh(mesh);
    globalThis.__mesh = mesh;

    $('<npc>', { id: 'hero' }).at(100, 160).size(28, 40).appendTo($.world);
    // Цель без физического тела — агент доходит точно до точки, не упираясь.
    $('<sprite>', { id: 'goal' }).at(520, 160).appendTo($.world);
});
